    tourAnalyticsAccBody: 'यहाँ दिखता है कि Ope के पूर्वानुमान असल में हुई बात के कितने क़रीब रहे। Ope आमतौर पर मोटे अंदाज़ से शुरू करता है और आपके ढर्रे सीखते-सीखते सटीक होता जाता है। सुधार यहाँ असली प्रतिशत में दिखेगा — संख्या जितनी कम, पूर्वानुमान उतना भरोसेमंद।',
