    tomorrowLabel: 'غدًا — {day}',
    tourAnalyticsAccBody: 'يُظهر هنا مدى قرب توقعات Ope مما حدث فعلاً. يبدأ Ope عادةً تقريبياً ثم يزداد دقة كلما تعلّم أنماطك. سترى التحسّن هنا كنسبة حقيقية — كلما صغر الرقم زادت ثقتك بالتوقع.',
    tourAnalyticsAccTitle: 'دقة التوقع',
    tourAnalyticsAdsBody: 'إن كنت قد وسمت حملات إعلانية أو فعاليات خاصة في الإدارة، يعرض Ope الزيادة — كم زبوناً إضافياً جلبت كل واحدة مقارنةً بمستواك المعتاد المتوقع. الزيادة الموجبة تعني أن العرض نجح؛ والنتيجة المستوية تعني أنه غالباً لم يستحق.',
    tourAnalyticsAdsTitle: 'أثر الإعلانات والفعاليات',
    tourAnalyticsBody: 'ستجد هنا دقة التوقعات، وتوصيات عدد الموظفين لساعات الذروة، وأثر أي إعلانات أو فعاليات وسمتها، وربحية زبائنك الأوفياء.',
    tourAnalyticsRegBody: 'ترى هنا كم مرة يزورك كل زبون دائم وكم يضيف إلى نشاطك مع الوقت. وإن بدأت زيارات أحدهم تتراجع، ينبّهك Ope لتتواصل معه قبل أن تفقده.',
    tourAnalyticsRegTitle: 'زبائنك الأوفياء',
    tourAnalyticsStaffBody: 'بناءً على أنماط ساعات الذروة لديك، يخبرك Ope بعدد الموظفين اللازم في كل ساعة من اليوم. كما يبيّن ما يحدث للطابور إن أضفت شخصاً أو استغنيت عنه — فترى بالضبط متى يُحدث زوجُ يدين إضافي فرقاً حقيقياً.',
    tourAnalyticsStaffTitle: 'توصيات الموظفين',
    tourAnalyticsTitle: 'التحليلات — افهم أنماطك',
    tourBack: 'رجوع →',
    tourDarkModeBody: 'يعمل Ope في الوضعين الفاتح والداكن. استخدم الزر أدناه للتبديل — جرّبه الآن! يمكنك تغييره في أي وقت.',
    tourDarkModeTitle: 'اختر مظهرك — داكن أم فاتح؟',
    tourDoneBody: 'يصبح Ope أذكى كلما سجّلت أكثر. ابدأ بتسجيل مبيعات اليوم — ثم عد بعد أسبوعين لرؤية توقعك الأول. يمكنك إعادة تشغيل هذه الجولة في أي وقت من الإعدادات.',
    tourDoneTitle: 'أنت جاهز تمامًا!',
    tourFinish: 'لنبدأ!',
    tourForecastBody: 'بمجرد تسجيل بضعة أيام، يعرض هذا الرسم البياني مدى ازدحام كل يوم من الأسبوع القادم على الأرجح — حتى تتمكن من التخطيط مسبقًا. تزداد دقته كلما سجّلت أكثر.',
    tourForecastBusyBody: 'مرّر لأسفل في شاشة التوقعات لترى أي ساعات الغد يُتوقع أن تكون الأكثر ازدحاماً وكم موظفاً قد تحتاج في كل ساعة. ويُظهر Ope أيضاً أثر تغيير فريقك بشخص واحد على أوقات انتظار الزبائن — لتخطط بثقة.',
    tourForecastBusyTitle: 'ساعات الذروة والموظفون',
    tourForecastTitle: 'توقع الطلب الخاص بك',
    tourFriendlyModeBody: 'المفتاح المميَّز يفعّل وضع اللغة البسيطة، الذي يستبدل المصطلحات التقنية (مثل "MAPE" أو "مخزون الأمان") بكلمات يومية بسيطة. اضغطه الآن لتجربته — يمكنك إيقافه في أي وقت.',
    tourFriendlyModeTitle: 'تفضّل صياغة أبسط؟',
    tourLogBody: 'هذا هو التبويب الذي ستستخدمه كل يوم. سجّل كل عملية بيع لحظة حدوثها، أو أدخل هنا إجماليات نهاية اليوم. كلما سجّلت أكثر ازداد Ope ذكاءً.',
    tourLogRegularBody: 'اضغط "تسجيل زبون دائم" أسفل أزرار البيع لتسجيل زيارة زبون وفيّ. يمكنك إضافة ما أنفقه — يتابع Ope قيمة كل زبون دائم مع الوقت ويخبرك إن غاب أحدهم مدة.',
    tourLogRegularTitle: 'تسجيل زيارة عميل دائم',
    tourLogTitle: 'تبويب التسجيل — عملك اليومي',
    tourManageBody: 'تحت الإدارة ستجد منتجاتك، عملاءك الدائمين المخلصين، الأنماط المتكررة، العروض، والإعدادات. هنا تعلّم Ope عن عملك — كلما أضفت أكثر، ازداد ذكاء التطبيق.',
    tourManageCurrencyBody: 'من الإعدادات، اختر العملة التي يعمل بها نشاطك. كل مبلغ يعرضه Ope يستخدمها — الأسعار، وما ينفقه زبائنك الدائمون، وتكلفة الإعلان.',
    tourManageCurrencyTitle: 'عملتك',
    tourManagePastBody: 'نسيت تسجيل يوم؟ اضغط هنا لتعبئته أو لتصحيح يوم سبق تسجيله. السجل الكامل يجعل التوقعات أحدّ. حتى تعبئة أسبوع واحد من الأيام الفائتة تحسّن دقة Ope بوضوح.',
    tourManagePastTitle: 'الأيام السابقة',
    tourManagePatBody: 'أخبر Ope بالأحداث المتكررة — كرحلة مدرسية كل أحد — وسيتعامل معها كأمر متوقع لا كأيام غريبة. وكلما علّمت Ope أنماطاً أكثر تحسّنت توقعاته وقلّت التنبيهات الكاذبة.',
    tourManagePatTitle: 'الأنماط المتكررة',
    tourManageProdBody: 'أضف أو عدّل هنا المنتجات التي تبيعها. يكفي اسم ووحدة للبدء. وبمجرد إضافة منتج يتابع Ope الطلب واحتياج إعادة الطلب تلقائياً. ويمكنك اختيارياً إضافة مهلة المورّد وعدد المخزون ومدة الصلاحية للحصول على نصائح طلب كاملة.',
    tourManageProdTitle: 'منتجاتك',
    tourManageSimpleLangBody: 'تحت الإدارة ← الإعدادات، ستجد مفتاح "لغة بسيطة". فعّله وسيستبدل Ope المصطلحات التقنية — مثل "MAPE" أو "مخزون الأمان" أو "FIFO" — بكلمات يومية بسيطة. رائع إذا شعرت أن أي تسمية غير مألوفة. تحصل كل من الإنجليزية والعبرية على النسخة المبسّطة. تستخدم الجولة نفسها أيضًا الصياغة الأبسط عند تفعيل هذا الوضع.',
    tourManageSimpleLangTitle: 'وضع اللغة البسيطة',
    tourManageTitle: 'الإدارة',
    tourNext: '← التالي',
    tourOrderBody: 'مرّر لأسفل في شاشة التوقعات لترى نصائح إعادة الطلب — يخبرك Ope بالضبط بما تطلبه ومتى، بناءً على مُهَل التوريد وسرعة بيع كل منتج.',
