    tourWelcomeBody: 'يساعدك Ope على معرفة مدى ازدحام عملك — حتى تطلب المخزون المناسب، وتجدول الموظفين المناسبين، ولا تُفاجأ أبدًا. دعنا نلقي نظرة سريعة على ما هو موجود هنا.',
