    todayLabel: 'hoje',
    tomorrowHourByHour: 'Amanhã hora a hora',
    tomorrowLabel: 'Amanhã — {day}',
    tourAnalyticsAccBody: 'Mostra o quão perto as previsões do Ope ficaram do que realmente aconteceu. O Ope costuma começar impreciso e ganhar pontaria à medida que aprende os seus padrões. Verá aqui essa melhoria como uma percentagem real — quanto menor o número, mais pode confiar na previsão.',
    tourAnalyticsAccTitle: 'Precisão da previsão',
    tourAnalyticsAdsBody: 'Se marcou campanhas ou eventos especiais em Gerir, o Ope mostra o ganho — quantos clientes a mais cada um trouxe face ao seu nível normal esperado. Um ganho positivo significa que a promoção resultou; um resultado plano significa que provavelmente não valeu a pena.',
    tourAnalyticsAdsTitle: 'Impacto de anúncios e eventos',
    tourAnalyticsBody: 'Aqui encontra a precisão das previsões, recomendações de pessoal para as suas horas de pico, o ganho de quaisquer anúncios ou eventos que tenha marcado, e a rentabilidade dos seus clientes fiéis.',
    tourAnalyticsRegBody: 'Aqui vê com que frequência cada cliente habitual o visita e quanto contribui para o seu negócio ao longo do tempo. Se as visitas de um habitual começarem a cair, o Ope assinala-o para que possa contactá-lo antes de o perder.',
    tourAnalyticsRegTitle: 'Os seus clientes fiéis',
    tourAnalyticsStaffBody: 'Com base nos seus padrões de horas de pico, o Ope diz-lhe quantas pessoas precisa a cada hora do dia. Também mostra o que acontece à sua fila se acrescentar ou retirar uma pessoa — para ver exactamente quando um par de mãos a mais faz diferença real.',
    tourAnalyticsStaffTitle: 'Recomendações de pessoal',
    tourAnalyticsTitle: 'Análises — compreenda os seus padrões',
    tourBack: '← Voltar',
    tourDarkModeBody: 'O Ope funciona em modo claro e escuro. Use o botão abaixo para trocar — experimente! Pode mudar quando quiser.',
    tourDarkModeTitle: 'Escolha sua aparência — escura ou clara?',
    tourDoneBody: 'O Ope fica mais inteligente quanto mais você registra. Comece registrando as vendas de hoje — depois volte em algumas semanas para ver sua primeira previsão. Você pode rever este tour a qualquer momento em Configurações.',
    tourDoneTitle: 'Tudo pronto!',
    tourFinish: 'Vamos lá!',
    tourForecastBody: 'Depois que você registrar alguns dias, este gráfico mostra o quanto cada dia da próxima semana deve movimentar — para você se planejar. Fica mais preciso quanto mais você registra.',
    tourForecastBusyBody: 'Desloque-se para baixo no ecrã Previsão para ver que horas de amanhã devem ser as mais movimentadas e quantas pessoas poderá precisar em cada hora. O Ope mostra ainda o efeito de mudar a equipa numa pessoa nos tempos de espera — para poder planear com confiança.',
    tourForecastBusyTitle: 'Horas de pico e pessoal',
    tourForecastTitle: 'Sua previsão de demanda',
    tourFriendlyModeBody: 'O botão destacado ativa o modo Linguagem simples, que substitui termos técnicos (como "MAPE" ou "margem de segurança") por palavras simples do dia a dia. Aperte agora para experimentar — você pode desativar a qualquer momento.',
    tourFriendlyModeTitle: 'Prefere uma linguagem mais simples?',
    tourLogBody: 'Este é o separador que vai usar todos os dias. Registe cada venda no momento, ou introduza aqui os totais do fim do dia. Quanto mais registar, mais esperto fica o Ope.',
    tourLogRegularBody: 'Toque em "Registar habitual" por baixo dos botões de venda para registar a visita de um cliente fiel. Pode indicar quanto gastou — o Ope acompanha o valor de cada habitual ao longo do tempo e avisa-o se algum já não aparece há uns tempos.',
    tourLogRegularTitle: 'Registrar cliente fiel',
    tourLogTitle: 'Separador Registar — a sua ação diária',
    tourManageBody: 'Em Gerenciar você encontra seus produtos, clientes fiéis, padrões recorrentes, promoções e configurações. É aqui que você ensina ao Ope sobre seu negócio — quanto mais você adiciona, mais inteligente ele fica.',
    tourManageCurrencyBody: 'Nas Definições, escolha a moeda com que o seu negócio trabalha. Todos os valores do Ope a usam — preços, o que os habituais gastam, quanto custou um anúncio.',
    tourManageCurrencyTitle: 'Sua moeda',
    tourManagePastBody: 'Esqueceu-se de registar um dia? Toque aqui para o preencher ou corrigir um dia já registado. Um histórico completo torna as previsões mais afiadas. Mesmo preencher uma semana em falta melhora visivelmente a precisão do Ope.',
    tourManagePastTitle: 'Dias anteriores',
    tourManagePatBody: 'Conte ao Ope sobre eventos regulares — como uma visita de escola todos os domingos — e ele tratá-los-á como esperados, não como dias estranhos. Quantos mais padrões ensinar ao Ope, melhores as previsões e menos alertas falsos vai receber.',
    tourManagePatTitle: 'Padrões recorrentes',
    tourManageProdBody: 'Adicione ou edite aqui os produtos que vende. Um nome e uma unidade bastam para começar. Assim que um produto existe, o Ope acompanha a procura e a necessidade de encomenda automaticamente. Pode ainda indicar prazo do fornecedor, contagem de stock e prazo de validade para conselhos de encomenda completos.',
    tourManageProdTitle: 'Seus produtos',
    tourManageSimpleLangBody: 'Em Gerenciar → Configurações, você encontra um botão de "Linguagem simples". Ative e o Ope substitui termos técnicos — como "MAPE", "margem de segurança" ou "FIFO" — por palavras simples do dia a dia. Ótimo se algum rótulo parecer estranho. Tanto o inglês quanto o hebraico têm a versão simples. O próprio tour também usa a linguagem mais simples quando esse modo está ativo.',
    tourManageSimpleLangTitle: 'Modo de linguagem simples',
    tourManageTitle: 'Gerenciar',
    tourNext: 'Próximo →',
    tourOrderBody: 'Desloque-se para baixo no ecrã Previsão para ver os conselhos de encomenda — o Ope diz-lhe exactamente o que encomendar e quando, com base nos seus prazos de entrega e na rapidez com que cada produto se vende.',
    tourOrderTitle: 'O que pedir',
    tourReplayBtn: 'Repetir tour',
    tourReplayDesc: 'Veja de novo o passo a passo do Ope desde o início.',
    tourReplayLabel: 'Tour guiado',
    tourSaleBody: 'Toque nos botões dos produtos uma vez por cada artigo vendido. O Ope guarda a hora exacta, por isso o seu gráfico de horas de pico constrói-se sozinho ao longo do dia.',
    tourSaleTitle: 'Toque para registar vendas',
    tourSectionPreferences: 'Preferências',
    tourSkipAll: 'Pular tour',
    tourSkipSection: 'Pular {section}',
    tourSkipStep: 'Pular esta etapa',
    tourWelcomeBody: 'O Ope ajuda você a saber o quanto seu negócio vai movimentar — para você pedir o estoque certo, escalar a equipe certa e nunca ser pego de surpresa. Vamos dar uma olhada rápida no que tem aqui.',
