    tomorrowLabel: 'Завтра — {day}',
    tourAnalyticsAccBody: 'Здесь видно, насколько прогнозы Ope совпали с тем, что произошло на самом деле. Обычно Ope начинает грубо и становится точнее, узнавая ваши закономерности. Улучшение показано настоящим процентом — чем меньше число, тем больше можно полагаться на прогноз.',
    tourAnalyticsAccTitle: 'Точность прогноза',
    tourAnalyticsAdsBody: 'Если вы отметили рекламные кампании или особые события в «Управлении», Ope покажет прирост — сколько дополнительных клиентов принесло каждое по сравнению с обычным ожидаемым уровнем. Положительный прирост значит, что акция сработала; ровный результат — что она, скорее всего, того не стоила.',
