    tourAnalyticsBody: 'Здесь собраны точность прогнозов, рекомендации по персоналу на часы пик, прирост от отмеченных вами реклам и событий, а также доходность ваших постоянных клиентов.',
    tourAnalyticsRegBody: 'Здесь видно, как часто приходит каждый постоянный клиент и сколько он приносит вашему делу со временем. Если его визиты начинают редеть, Ope это отметит, и вы успеете связаться с ним до того, как потеряете.',
