    tourAnalyticsStaffBody: 'По вашим часам пик Ope подскажет, сколько людей нужно в каждый час дня. Он также покажет, что станет с очередью, если добавить или убрать одного человека — так видно, когда лишняя пара рук действительно что-то меняет.',
