    tourDarkModeBody: 'Ope работает и в светлом, и в тёмном режиме. Переключите кнопкой ниже — попробуйте прямо сейчас! Менять можно в любое время.',
    tourDarkModeTitle: 'Выберите внешний вид — тёмный или светлый?',
    tourDoneBody: 'Ope становится умнее по мере того, как вы вносите данные. Начните с записи сегодняшних продаж — а затем загляните через пару недель, чтобы увидеть свой первый прогноз. Вы можете повторить этот тур в любое время из настроек.',
    tourDoneTitle: 'Всё готово!',
