    tourManagePastTitle: 'Прошлые дни',
    tourManagePatBody: 'Расскажите Ope о регулярных событиях — например, о школьной экскурсии каждое воскресенье — и он будет считать их ожидаемыми, а не странными. Чем больше закономерностей вы ему объясните, тем лучше прогнозы и тем меньше ложных тревог.',
    tourManagePatTitle: 'Повторяющиеся паттерны',
    tourManageProdBody: 'Здесь добавляйте и изменяйте товары, которые продаёте. Для начала хватит названия и единицы измерения. Как только товар появился, Ope сам следит за спросом и потребностью в заказе. По желанию укажите срок поставки, остаток и срок годности — тогда советы по заказам будут полными.',
    tourManageProdTitle: 'Ваши товары',
    tourManageSimpleLangBody: 'В разделе Управление → Настройки есть переключатель «Простой язык». Включите его, и Ope заменит технические термины — такие как «MAPE», «запас прочности» или «FIFO» — простыми повседневными словами. Отлично, если какая-то подпись кажется незнакомой. Упрощённая версия доступна на английском и иврите. Сам тур тоже использует более простые формулировки, когда этот режим включён.',
    tourManageSimpleLangTitle: 'Режим простого языка',
    tourManageTitle: 'Управление',
    tourNext: 'Далее →',
    tourOrderBody: 'Пролистайте экран прогноза вниз до советов по заказам — Ope точно скажет, что и когда заказать, исходя из сроков поставки и того, как быстро расходится каждый товар.',
    tourOrderTitle: 'Что заказать',
