    todayLabel: "aujourd'hui",
    tomorrowHourByHour: 'Demain heure par heure',
    tomorrowLabel: 'Demain — {day}',
    tourAnalyticsAccBody: "Vous voyez ici à quel point les prévisions d'Ope ont collé à la réalité. Ope commence en général approximatif puis s'affine à mesure qu'il apprend vos habitudes. L'amélioration s'affiche en pourcentage réel — plus le chiffre est bas, plus vous pouvez vous fier à la prévision.",
    tourAnalyticsAccTitle: 'Fiabilité des prévisions',
    tourAnalyticsAdsBody: "Si vous avez marqué des campagnes ou des événements dans Gérer, Ope en montre le gain — combien de clients supplémentaires chacun a apportés par rapport à votre niveau normal attendu. Un gain positif veut dire que l'opération a marché ; un résultat plat qu'elle n'en valait sans doute pas la peine.",
    tourAnalyticsAdsTitle: 'Impact des publicités et événements',
    tourAnalyticsBody: 'Vous trouverez ici la précision des prévisions, les recommandations de personnel pour vos heures de pointe, le gain des publicités ou événements que vous avez marqués, et la rentabilité de vos habitués.',
    tourAnalyticsRegBody: "Vous voyez ici à quelle fréquence chaque habitué vient et ce qu'il apporte à votre établissement au fil du temps. Si les visites d'un habitué s'espacent, Ope le signale pour que vous puissiez le relancer avant de le perdre.",
    tourAnalyticsRegTitle: 'Vos clients fidèles',
    tourAnalyticsStaffBody: "À partir de vos heures de pointe, Ope vous dit combien de personnes il faut à chaque heure de la journée. Il montre aussi ce qui arrive à la file si vous ajoutez ou retirez quelqu'un — vous voyez précisément quand une paire de bras en plus change vraiment les choses.",
    tourAnalyticsStaffTitle: 'Recommandations de personnel',
    tourAnalyticsTitle: 'Analyses — comprenez vos habitudes',
    tourBack: '← Retour',
    tourDarkModeBody: 'Ope fonctionne en mode clair comme en mode sombre. Utilisez le bouton ci-dessous pour changer — essayez ! Vous pourrez le modifier quand vous voudrez.',
    tourDarkModeTitle: 'Choisissez votre style — sombre ou clair ?',
    tourDoneBody: "Ope devient plus intelligent à mesure que vous enregistrez. Commencez par enregistrer les ventes d'aujourd'hui — puis revenez dans quelques semaines pour voir votre première prévision. Vous pouvez rejouer ce tour à tout moment depuis Paramètres.",
    tourDoneTitle: 'Vous êtes prêt !',
    tourFinish: 'Allons-y !',
    tourForecastBody: "Une fois quelques jours enregistrés, ce graphique montre à quel point chaque jour de la semaine à venir sera probablement chargé — pour que vous puissiez planifier à l'avance. Il devient plus précis à mesure que vous enregistrez.",
    tourForecastBusyBody: "Faites défiler l'écran Prévision pour voir quelles heures de demain devraient être les plus chargées et combien de personnes prévoir à chaque heure. Ope montre aussi l'effet d'une personne en plus ou en moins sur le temps d'attente — de quoi planifier sereinement.",
    tourForecastBusyTitle: 'Heures de pointe et personnel',
    tourForecastTitle: 'Votre prévision de demande',
    tourFriendlyModeBody: "L'interrupteur mis en évidence active le mode Langage simple, qui remplace les termes techniques (comme « MAPE » ou « marge de sécurité ») par des mots simples du quotidien. Appuyez dessus maintenant pour essayer — vous pouvez le désactiver à tout moment.",
    tourFriendlyModeTitle: 'Vous préférez une formulation plus simple ?',
    tourLogBody: "C'est l'onglet que vous utiliserez tous les jours. Enregistrez chaque vente au moment où elle se fait, ou saisissez ici vos totaux de fin de journée. Plus vous saisissez, plus Ope devient fin.",
    tourLogRegularBody: "Touchez « Enregistrer un habitué » sous les boutons de vente pour noter la visite d'un client fidèle. Vous pouvez indiquer ce qu'il a dépensé — Ope suit la valeur de chaque habitué dans le temps et vous prévient si l'un d'eux n'est pas venu depuis un moment.",
    tourLogRegularTitle: 'Enregistrer un habitué',
    tourLogTitle: 'Onglet Saisie — votre geste quotidien',
    tourManageBody: "Sous Gérer, vous trouverez vos produits, habitués fidèles, modèles récurrents, promos, et paramètres. C'est ici que vous apprenez à Ope à connaître votre entreprise — plus vous en ajoutez, plus elle devient intelligente.",
    tourManageCurrencyBody: "Dans les Réglages, choisissez la monnaie de votre établissement. Tous les montants d'Ope l'utilisent — prix, dépenses de vos habitués, coût d'une publicité.",
    tourManageCurrencyTitle: 'Votre devise',
    tourManagePastBody: "Vous avez oublié de saisir une journée ? Touchez ici pour la compléter ou corriger une journée déjà saisie. Un historique complet affûte les prévisions. Combler ne serait-ce qu'une semaine manquante améliore nettement la précision d'Ope.",
    tourManagePastTitle: 'Jours passés',
    tourManagePatBody: 'Parlez à Ope des événements réguliers — comme une sortie scolaire tous les dimanches — et il les traitera comme attendus, pas comme des journées bizarres. Plus vous lui apprenez de motifs, meilleures sont ses prévisions et moins vous recevrez de fausses alertes.',
    tourManagePatTitle: 'Modèles récurrents',
    tourManageProdBody: "Ajoutez ou modifiez ici les produits que vous vendez. Un nom et une unité suffisent pour démarrer. Dès qu'un produit existe, Ope suit automatiquement la demande et les besoins de réassort. Vous pouvez aussi renseigner le délai fournisseur, le stock et la durée de conservation pour des conseils de commande complets.",
    tourManageProdTitle: 'Vos produits',
    tourManageSimpleLangBody: "Sous Gérer → Paramètres, vous trouverez un interrupteur « Langage simple ». Activez-le et Ope remplace les termes techniques — comme « MAPE », « marge de sécurité », ou « FIFO » — par des mots simples du quotidien. Utile si un libellé semble peu familier. L'anglais et l'hébreu ont tous deux la version simple. La visite guidée elle-même utilise aussi la formulation plus simple quand ce mode est activé.",
    tourManageSimpleLangTitle: 'Mode langage simple',
    tourManageTitle: 'Gérer',
    tourNext: 'Suivant →',
    tourOrderBody: "Faites défiler l'écran Prévision pour voir les conseils de commande — Ope vous dit exactement quoi commander et quand, d'après vos délais de livraison et la vitesse à laquelle chaque produit part.",
