    teachOpeDesc: 'আপনি জানেন এমন পুনরাবৃত্ত প্যাটার্ন ঘোষণা করুন — যেমন প্রতি রবিবার একটি স্কুল ট্রিপ — এবং Ope সেগুলোকে অস্বাভাবিক হিসেবে চিহ্নিত না করে প্রত্যাশা করবে।',
    teachOpeTitle: 'Ope-কে আপনার জগৎ শেখান',
