    tourFinish: 'چلیں شروع کرتے ہیں!',
    tourForecastBody: 'چند دن درج کرنے کے بعد، یہ چارٹ دکھاتا ہے کہ آنے والے ہفتے کا ہر دن کتنا مصروف ہو سکتا ہے — تاکہ آپ پہلے سے منصوبہ بندی کر سکیں۔ جتنا زیادہ آپ درج کریں گے، یہ اتنا ہی درست ہوتا جائے گا۔',
    tourForecastBusyBody: 'پیش گوئی کی اسکرین پر نیچے جائیں اور دیکھیں کہ کل کے کون سے گھنٹے سب سے مصروف متوقع ہیں اور ہر گھنٹے کتنے افراد درکار ہو سکتے ہیں۔ Ope یہ بھی دکھاتا ہے کہ ٹیم میں ایک فرد کی تبدیلی گاہکوں کے انتظار پر کیا اثر ڈالے گی — تاکہ آپ اطمینان سے منصوبہ بنا سکیں۔',
    tourForecastBusyTitle: 'مصروف اوقات اور عملہ',
    tourForecastTitle: 'آپ کی طلب کی پیشگوئی',
    tourFriendlyModeBody: 'نمایاں ٹوگل سادہ زبان موڈ آن کرتا ہے، جو تکنیکی اصطلاحات (جیسے "MAPE" یا "حفاظتی بفر") کو سادہ روزمرہ الفاظ سے بدل دیتا ہے۔ ابھی آزمانے کے لیے دبائیں — آپ اسے کسی بھی وقت بند کر سکتے ہیں۔',
    tourFriendlyModeTitle: 'سادہ الفاظ ترجیح دیتے ہیں؟',
    tourLogBody: 'یہی وہ ٹیب ہے جو آپ روز استعمال کریں گے۔ ہر فروخت اسی وقت درج کریں، یا یہاں دن کے اختتام کے کل درج کریں۔ آپ جتنا زیادہ درج کریں گے، Ope اتنا ہی سمجھدار ہوگا۔',
    tourLogRegularBody: "کسی وفادار گاہک کی آمد درج کرنے کے لیے فروخت کے بٹنوں کے نیچے 'مستقل گاہک درج کریں' دبائیں۔ آپ یہ بھی شامل کر سکتے ہیں کہ اس نے کتنا خرچ کیا — Ope ہر مستقل گاہک کی قدر وقت کے ساتھ رکھتا ہے اور بتاتا ہے اگر کوئی کافی عرصے سے نہ آیا ہو۔",
    tourLogRegularTitle: 'مستقل گاہک ریکارڈ کریں',
    tourLogTitle: 'درج کریں ٹیب — آپ کا روزمرہ کام',
    tourManageBody: 'انتظام کے تحت آپ کو اپنی مصنوعات، وفادار مستقل گاہک، دہرائے جانے والے پیٹرن، پروموشنز، اور ترتیبات ملیں گی۔ یہ وہ جگہ ہے جہاں آپ Ope کو اپنے کاروبار کے بارے میں سکھاتے ہیں — جتنا زیادہ آپ شامل کریں گے، یہ اتنا ہی ہوشیار ہو جائے گا۔',
    tourManageCurrencyBody: 'ترتیبات میں وہ کرنسی منتخب کریں جس میں آپ کا کاروبار چلتا ہے۔ Ope جو بھی رقم دکھاتا ہے وہی استعمال ہوتی ہے — قیمتیں، مستقل گاہکوں کا خرچ، اشتہار کی لاگت۔',
    tourManageCurrencyTitle: 'آپ کی کرنسی',
    tourManagePastBody: 'کوئی دن درج کرنا بھول گئے؟ اسے بھرنے یا پہلے درج کیے گئے دن کو درست کرنے کے لیے یہاں دبائیں۔ مکمل تاریخ پیش گوئیوں کو تیز کرتی ہے۔ صرف ایک ہفتے کے چھوٹے ہوئے دن بھرنا بھی Ope کی درستی نمایاں طور پر بہتر کر دیتا ہے۔',
    tourManagePastTitle: 'گزشتہ دن',
    tourManagePatBody: 'Ope کو باقاعدہ ہونے والے واقعات بتائیں — جیسے ہر اتوار اسکول کا دورہ — تو وہ انہیں غیر معمولی نہیں بلکہ متوقع سمجھے گا۔ آپ Ope کو جتنے زیادہ انداز سکھائیں گے، اس کی پیش گوئیاں اتنی بہتر ہوں گی اور جھوٹے انتباہ اتنے کم۔',
    tourManagePatTitle: 'دہرائے جانے والے پیٹرن',
    tourManageProdBody: 'یہاں اپنی بیچی جانے والی مصنوعات شامل یا تبدیل کریں۔ شروع کرنے کے لیے صرف نام اور اکائی کافی ہے۔ مصنوعات شامل ہوتے ہی Ope طلب اور دوبارہ آرڈر کی ضرورت خود بخود دیکھتا رہتا ہے۔ مکمل آرڈر مشورے کے لیے آپ چاہیں تو سپلائر کا وقت، اسٹاک کی گنتی اور مدتِ افادیت بھی شامل کر سکتے ہیں۔',
    tourManageProdTitle: 'آپ کی مصنوعات',
