    tourSkipStep: 'Diesen Schritt überspringen',
    tourWelcomeBody: 'Ope hilft Ihnen zu wissen, wie geschäftig Ihr Betrieb sein wird — damit Sie den richtigen Bestand bestellen, das richtige Personal einplanen und nie überrascht werden. Machen wir eine kurze Tour durch das, was hier ist.',
