    tourAnalyticsAccBody: 'Ope の予測が実際とどれだけ近かったかを示します。Ope はたいてい粗いところから始まり、あなたの傾向を学ぶほど精度が上がります。その改善が実際の割合として表示されます — 数字が小さいほど、予測を頼りにできます。',
    tourAnalyticsAccTitle: '予測精度',
    tourAnalyticsAdsBody: '管理タブで広告キャンペーンや特別イベントに印を付けていれば、Ope はその上乗せ分を表示します — それぞれが通常の見込み水準に比べて何人多く呼んだか。プラスなら販促は効いた証拠、横ばいならおそらく見合わなかったということです。',
    tourAnalyticsAdsTitle: '広告・イベントの効果',
    tourAnalyticsBody: 'ここには予測の精度、混雑時間の人員配置の提案、印を付けた広告やイベントの効果、常連のお客さまの収益性がまとまっています。',
    tourAnalyticsRegBody: '常連のお客さまがどれくらいの頻度で来店し、時間とともにどれだけお店に貢献しているかが分かります。来店が減り始めた方がいれば Ope が知らせるので、失う前に声をかけられます。',
    tourAnalyticsRegTitle: '常連のお客さま',
    tourAnalyticsStaffBody: '混雑時間の傾向をもとに、Ope は1日の各時間帯に何人必要かを伝えます。人を1人増減したときに行列がどうなるかも示すので、あと一人の手がいつ本当に効くのかがはっきり分かります。',
    tourAnalyticsStaffTitle: '人員配置の提案',
    tourAnalyticsTitle: '分析 — 自分の傾向を知る',
    tourBack: '← 戻る',
    tourDarkModeBody: 'Ope はライトでもダークでも使えます。下のボタンで切り替えられます — 今すぐお試しを！いつでも変更できます。',
    tourDarkModeTitle: '好みの見た目を選ぶ — ダークかライトか？',
    tourDoneBody: 'Opeは記録するほど賢くなります。まずは今日の販売を記録することから始めましょう — そして数週間後に戻ってきて最初の予測を確認してください。このツアーは「設定」からいつでも再生できます。',
    tourDoneTitle: '準備完了です！',
    tourFinish: '始めましょう！',
    tourForecastBody: '数日分の記録が集まると、このグラフに来週の各曜日がどれくらい忙しくなりそうかが表示され、事前に計画を立てられます。記録するほど精度が上がります。',
    tourForecastBusyBody: '予測画面を下にスクロールすると、明日どの時間帯が最も混みそうか、各時間に何人必要になりそうかが分かります。Ope は人員を1人変えたときの待ち時間への影響も示すので、安心してシフトを組めます。',
    tourForecastBusyTitle: '混雑時間と人員',
    tourForecastTitle: '需要予測',
    tourFriendlyModeBody: 'ハイライトされたトグルで「やさしい言葉」モードがオンになり、「MAPE」や「安全バッファー」などの専門用語が日常的な言葉に置き換わります。今すぐ押して試してみてください — いつでもオフにできます。',
    tourFriendlyModeTitle: 'よりシンプルな言葉がお好みですか？',
    tourLogBody: '毎日使うのがこのタブです。売れたその場でタップするか、閉店後の合計をここに入力してください。記録が増えるほど Ope は賢くなります。',
    tourLogRegularBody: '売上ボタンの下の「常連客を記録」をタップして、常連のお客さまの来店を記録します。使った金額も入力できます — Ope は常連ごとの価値を時間とともに追い、しばらく来ていない方がいれば知らせます。',
    tourLogRegularTitle: '常連客を記録',
    tourLogTitle: '記録タブ — 毎日の作業',
    tourManageBody: '「管理」では、商品、ご贔屓の常連客、繰り返しパターン、プロモーション、設定が見つかります。ここでOpeにあなたのビジネスについて教えます — 追加するほど賢くなります。',
    tourManageCurrencyBody: '設定で、お店で使う通貨を選んでください。Ope が表示する金額はすべてそれを使います — 価格、常連客の支出、広告の費用。',
    tourManageCurrencyTitle: '通貨の設定',
    tourManagePastBody: '記録し忘れた日がありますか？ここをタップして埋めるか、記録済みの日を直せます。履歴がそろうほど予測は鋭くなります。抜けた1週間を埋めるだけでも、Ope の精度は目に見えて上がります。',
    tourManagePastTitle: '過去の日',
    tourManagePatBody: '毎週日曜の遠足のように繰り返し起きることを Ope に教えると、異常な日ではなく想定内として扱われます。教えるパターンが増えるほど予測は良くなり、誤った警告は減ります。',
    tourManagePatTitle: '繰り返しパターン',
    tourManageProdBody: '扱っている商品をここで追加・編集します。始めるには名前と単位だけで十分です。商品を登録すれば、Ope が需要と発注の必要を自動で追います。発注アドバイスを万全にしたい場合は、仕入れの所要日数、在庫数、日持ちも任意で追加できます。',
    tourManageProdTitle: '取り扱い商品',
